    // Scales an n-bit colour channel to 8 bits by bit replication.
    function automatic [7:0] fs_expand8(input [63:0] v, input integer n);
        integer i;
        begin
            fs_expand8 = 8'd0;
            if (n >= 8) fs_expand8 = 8'(v >> (n - 8));
            else for (i = 0; i < 8; i = i + 1) fs_expand8[7 - i] = v[n - 1 - (i % n)];
        end
